    const beatPulse=1+Math.pow(1-state.beatPhase,5)*.5+state.visualKick*.18,holdBoost=state.held?1.35:1;
    state.trails.unshift({x,y,life:1});state.trails=state.trails.slice(0,18).map(v=>({...v,life:v.life*.84}));ctx.save();
